pub struct PacketBuilder<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> PacketBuilder<'a, 'b, A> {
  #[inline]
  pub fn add_protocol_version(&mut self, protocol_version: u16) {
    self.fbb_.push_slot::<u16>(Packet::VT_PROTOCOL_VERSION, protocol_version, 2);
  }
  #[inline]
  pub fn add_kind(&mut self, kind: MessageKind) {
    self.fbb_.push_slot::<MessageKind>(Packet::VT_KIND, kind, MessageKind::Unknown);
  }
  #[inline]
  pub fn add_client_id(&mut self, client_id: u64) {
    self.fbb_.push_slot::<u64>(Packet::VT_CLIENT_ID, client_id, 0);
  }
  #[inline]
  pub fn add_run_id(&mut self, run_id: u64) {
    self.fbb_.push_slot::<u64>(Packet::VT_RUN_ID, run_id, 0);
  }
  #[inline]
  pub fn add_sequence(&mut self, sequence: u64) {
    self.fbb_.push_slot::<u64>(Packet::VT_SEQUENCE, sequence, 0);
  }
  #[inline]
  pub fn add_sim_time_ns(&mut self, sim_time_ns: u64) {
    self.fbb_.push_slot::<u64>(Packet::VT_SIM_TIME_NS, sim_time_ns, 0);
  }
  #[inline]
  pub fn add_entities(&mut self, entities: flatbuffers::WIPOffset<flatbuffers::Vector<'b , flatbuffers::ForwardsUOffset<EntityState<'b >>>>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Packet::VT_ENTITIES, entities);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> PacketBuilder<'a, 'b, A> {
    let start = _fbb.start_table();
    PacketBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<Packet<'a>> {
    let o = self.fbb_.end_table(self.start_);
    flatbuffers::WIPOffset::new(o.value())
  }
}

